package dev.studyforge.banking.application; import dev.studyforge.banking.adapter.inmemory.*; import dev.studyforge.banking.domain.*; import java.time.*; import java.util.*; public final class BankingCore{private final UnitOfWork uow;private final DepositService deposits;private final WithdrawalService withdrawals;private final TransferService transfers;private final HistoryService history;public BankingCore(UnitOfWork u,DepositService d,WithdrawalService w,TransferService t,HistoryService h){uow=Objects.requireNonNull(u);deposits=d;withdrawals=w;transfers=t;history=h;}public static BankingCore inMemory(Clock clock,TransactionIdProvider ids,FeeStrategy withdrawalFee,FeeStrategy transferFee,List<NotificationPort> notifications){InMemoryAccountRepository a=new InMemoryAccountRepository();InMemoryTransactionRepository t=new InMemoryTransactionRepository();InMemoryUnitOfWork u=new InMemoryUnitOfWork(a,t);TransactionFactory f=new TransactionFactory(clock::instant,ids);return new BankingCore(u,new DepositService(u,f,notifications),new WithdrawalService(u,f,withdrawalFee,notifications),new TransferService(u,f,transferFee,notifications),new HistoryService(u));}public void open(Account account){uow.execute((a,t)->{a.add(account);return null;});}public Account account(AccountId id){return uow.execute((a,t)->a.findById(id).orElseThrow(()->new AccountNotFoundException(id)));}public Transaction deposit(Deposit c){return deposits.deposit(c);}public Transaction withdraw(Withdrawal c){return withdrawals.withdraw(c);}public Transaction transfer(Transfer c){return transfers.transfer(c);}public List<Transaction> history(){return history.all();}public List<Transaction> history(AccountId id){return history.forAccount(id);}}
